{
  "name": "opencode-rules",
  "version": "2.0.0",
  "description": "OpenCode plugin that discovers and injects markdown rules into system prompts",
  "main": "dist/src/index.js",
  "types": "dist/src/index.d.ts",
  "type": "module",
  "scripts": {
    "build": "tsc && bun run build-tui.mjs",
    "dev": "tsc --watch",
    "test": "vitest",
    "test:run": "vitest run",
    "lint": "eslint src tui",
    "format": "prettier --write 'src/**/*.ts' 'tui/**/*.tsx' 'tui/**/*.ts'",
    "format:check": "prettier --check 'src/**/*.ts' 'tui/**/*.tsx' 'tui/**/*.ts'",
    "clean": "rm -rf dist",
    "prepublishOnly": "bun run clean && bun run build"
  },
  "keywords": [
    "opencode",
    "plugin",
    "rules",
    "system-prompt",
    "typescript"
  ],
  "author": "Joe Maples <joe@maples.dev>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/frap129/opencode-rules.git"
  },
  "bugs": {
    "url": "https://github.com/frap129/opencode-rules/issues"
  },
  "files": [
    "dist",
    "!dist/**/*.test.*",
    "!dist/**/*.spec.*",
    "!dist/**/test-fixtures.*",
    "!dist/**/api-surface.typecheck.*",
    "src/",
    "!src/**/*.test.ts",
    "!src/**/*.spec.ts",
    "!src/test-fixtures.ts",
    "!src/api-surface.typecheck.ts",
    "tui/",
    "!tui/**/*.test.ts",
    "!tui/**/*.test.tsx",
    "!tui/**/*.spec.ts",
    "!tui/**/*.spec.tsx",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "import": "./dist/src/index.js"
    },
    "./server": {
      "types": "./dist/src/index.d.ts",
      "import": "./dist/src/index.js"
    },
    "./tui": {
      "types": "./dist/tui/index.d.ts",
      "import": "./dist/tui/index.js"
    }
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.0.0-beta-18999 <0.0.1",
    "@opentui/core": ">=0.4.5",
    "@opentui/solid": ">=0.4.5",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/client": "0.0.0-beta-18999",
    "@opencode-ai/plugin": "0.0.0-beta-18999",
    "@opencode-ai/theme": "0.0.0-beta-18999",
    "@opentui/core": "^0.5.10",
    "@opentui/solid": "^0.5.10",
    "@types/node": "^20.19.43",
    "@typescript-eslint/eslint-plugin": "^6.21.0",
    "@typescript-eslint/parser": "^6.21.0",
    "eslint": "^8.57.1",
    "prettier": "^3.9.6",
    "solid-js": "^1.9.15",
    "typescript": "^5.9.3",
    "vitest": "^1.6.1"
  },
  "dependencies": {
    "minimatch": "^9.0.9",
    "yaml": "^2.9.0"
  },
  "aube": {
    "allowBuilds": {
      "esbuild": true,
      "msgpackr-extract": true
    }
  }
}
